import {
  FROSTLINE_BOXES,
  FROSTLINE_SIZE,
  FROSTLINE_SPAWNS,
  FROSTLINE_STRUCTURES,
  FROSTLINE_WALLS,
} from "../frostline-layout";
import type { MapDefinition } from "./types";

/**
 * FROSTLINE — the winter 1v1 aim arena (40 × 32 m): a snowed-in military logistics outpost.
 * Gameplay solids are generated by art/blender/frostline/layout.py into frostline-layout.ts;
 * the render scene is art/blender/frostline → public/fps/models/frostline.glb (same pipeline as
 * Dustfront: culling sections, one mesh per material, GPU-instanced pines, meshopt).
 *
 * Routes: the central courtyard (main aim duel), the upper communications corridor with the one
 * elevated position (the comms walkway), and the lower industrial corridor with the covered
 * loading bay. Every solid is mirrored across x = 0.
 */
export const FROSTLINE: MapDefinition = {
  id: "frostline",
  name: "Frostline",
  // Out of the random Practice/PvP rotation until the real-GPU Chrome/Firefox checks are done
  // (docs/fps-map/FROSTLINE.md §6). Setting this to true is the one line that adds it.
  rotation: false,
  arena: FROSTLINE_SIZE,
  boxes: FROSTLINE_BOXES,
  structures: FROSTLINE_STRUCTURES,
  walls: FROSTLINE_WALLS,
  barriers: [],
  // Trodden snow over concrete: the existing concrete impacts and footsteps.
  floorSurface: "concrete",
  footsteps: {
    floor: "snow",
    // Exterior crate/container roofs are capped with snow in frost_kit.py.
    tops: Object.fromEntries(
      FROSTLINE_BOXES.filter((b) => !b.id.startsWith("bay-")).map((b) => [b.id, "snow" as const]),
    ),
    // The covered loading bay has a cleared concrete floor and uncovered wood pallets.
    regions: [{ x: 0, z: 14.75, w: 14, d: 2.5, surface: "concrete" }],
  },
  spawns: FROSTLINE_SPAWNS,
  bot: {
    openings: {
      // North spawn exit, then the lane south of the crate stack.
      center: [
        { x: 13, z: -4.2 },
        { x: 9.6, z: -1.0 },
        { x: -9.6, z: -1.0 },
      ],
      // North alley, the comms corridor in front of the walkway.
      north: [
        { x: 18.6, z: -10 },
        { x: 8, z: -10.8 },
        { x: -8, z: -10.8 },
      ],
      // South alley, the warehouse corridor.
      south: [
        { x: 18.6, z: 10 },
        { x: 8, z: 12.6 },
        { x: -8, z: 12.6 },
      ],
    },
    // The enemy's south spawn exit and north alley.
    sweep: [
      { x: -13, z: 4.2 },
      { x: -18.6, z: -10 },
    ],
    flanks: {
      north: [
        { x: -8, z: -10.8 },
        { x: 8, z: -10.8 },
      ],
      south: [
        { x: -8, z: 12.6 },
        { x: 8, z: 12.6 },
      ],
    },
    regroup: [{ x: 9.6, z: 0.4 }],
  },
  presentation: {
    modelUrl: "/fps/models/frostline.glb",
    // Low winter sun late in the afternoon over the south-west ridge, under a pale high overcast.
    // Snow bounces a lot of light, so the ground term is cool and bright and exposure sits a
    // little below Dustfront's. Lamps, lit windows and festive strings are emissive (baked light
    // on the snow), so no real-time lights are added. The haze starts beyond the playable 40 m.
    lighting: {
      background: 0xaebdcf,
      fog: { color: 0xbfcad8, near: 55, far: 300 },
      hemisphere: { sky: 0xc9d7ec, ground: 0x8d97a6, intensity: 1.35 },
      sun: { color: 0xffdcb8, intensity: 2.35, position: [-22, 15, 24] },
      environmentIntensity: 0.42,
      exposure: 0.94,
    },
    sky: { zenith: 0x56739a, horizon: 0xc6d0dc, haze: 0xe8d7c8 },
    // Static shadow map over the 40 × 32 m arena plus the band buildings, rendered once.
    shadow: { extent: 26, far: 65, mapSize: 2048 },
    // The farthest ridges sit within 160 m.
    viewDistance: 260,
    blockout: { concrete: 0xb9bfc6, metal: 0x6f7c88, wood: 0x8a6a48, floor: 0xe4e9ef },
  },
};
